### 14. Abstract Valkey Repository Base Class
**File:** `/Users/admin/project/integrated-search/outbound/repository/cache/src/main/kotlin/com/cowave/search/repository/cache/AbstractValkeyRepository.kt`

```kotlin
package com.cowave.search.repository.cache

import com.cowave.shared.serialization.defaultJson
import kotlinx.serialization.KSerializer
import org.springframework.data.redis.core.RedisTemplate

/**
 * `ValkeyRepository`는 valkey를 DB로써 사용하는 영속성 레이어의 리포지토리입니다.
 */
abstract class AbstractValkeyRepository<ID, V : Any> (
    private val redisTemplate: RedisTemplate<String, String>,
    private val serializer: KSerializer<V>,
) {

    private fun serialize(value: V): String = defaultJson.encodeToString(serializer, value)

    private fun deserialize(jsonString: String): V = defaultJson.decodeFromString(serializer, jsonString)

    /**
     * Missed keys에 대한 처리를 애플리케이션에서 주도적으로 할 수 있도록 반환에 null이 포함될 수 있습니다.
     */
    protected fun multiGet(keys: List<String>): List<V?> {
        return redisTemplate.opsForValue()
            .multiGet(keys)
            ?.map { it?.let(::deserialize) }
            ?: emptyList()
    }

    /**
     * Valkey는 DB로써 사용되므로 TTL을 가질 필요가 없습니다.
     * 그렇기 때문에 다량의 데이터를 저장할 때 set loop를 사용하지 않고 mset을 사용합니다.
     */
    protected fun multiSet(keyValuePairs: Map<String, V>) {
        redisTemplate.opsForValue()
            .multiSet(keyValuePairs.mapValues { serialize(it.value) })
    }

    abstract protected fun getKey(id: ID): String

    protected fun getKeys(ids: List<ID>): List<String> = ids.map { getKey(it) }
}
```

**Key Design Points:**
- Uses `defaultJson` from `com.cowave.shared.serialization` for serialization
- Valkey is treated as a persistent DB (no TTL)
- Null values included in results for miss tracking

